const crypto = require('crypto');

function verifyPassword(candidate, storedHash) {
    // 1. Create hash object
    const hash = crypto.createHash('sha256');

    // 2. Update with candidate (default encoding is utf8)
    hash.update(candidate);

    // 3. Get digest in hex format
    const generatedHash = hash.digest('hex');

    // 4. Constant-time comparison
    return crypto.timingSafeEqual(
        Buffer.from(generatedHash, 'hex'),
        Buffer.from(storedHash, 'hex')
    );
}

